def find_permutation(n, p):
    # Create a list of positions for each element in p
    pos = [0] * (n + 1)
    for i in range(1, n + 1):
        pos[p[i - 1]] = i

    # Function to find the cycle starting at x
    def find_cycle(x):
        cycle = []
        while x not in cycle:
            cycle.append(x)
            x = p[x - 1]
        return cycle

    # Check all cycles
    visited = [False] * (n + 1)
    for i in range(1, n + 1):
        if not visited[i]:
            cycle = find_cycle(i)
            if len(cycle) % 2 != 0:
                return [-1]
            for j in range(0, len(cycle), 2):
                visited[cycle[j]] = True
                visited[cycle[j + 1]] = True

    # Construct the permutation q
    q = [0] * (n + 1)
